EXTRACTOR_VERSION = "1.0.0"
PROCESSED = ROOT / "data" / "private_corpus" / "processed"
CORPUS_META = ROOT / "data" / "corpus"
FACTS = ROOT / "data" / "policy_facts.jsonl"
VISUALS = ROOT / "data" / "visual_resources.json"
