VOID = {"area", "base", "br", "col", "embed", "hr", "img", "input", "link", "meta", "source",
        "track", "wbr"}
SKIP = {"script", "style", "noscript", "svg", "template", "button", "form", "nav", "header",
        "footer", "iframe", "select"}
INLINE = {"a", "span", "strong", "b", "em", "i", "u", "sup", "sub", "small", "br", "abbr", "mark",
          "label", "time", "img"}
