# ---------------------------------------------------------------- minimal DOM -------------
@dataclass
class Node:
    tag: str
    attrs: dict[str, str]
    children: list[Node | str] = field(default_factory=list)

    @property
    def cls(self) -> str:
        return self.attrs.get("class", "")

    def text(self) -> str:
        out: list[str] = []
        for c in self.children:
            if isinstance(c, str):
                out.append(c)
            elif c.tag not in SKIP - {"button"}:
                out.append(c.text())
                if c.tag in ("br", "p", "li", "div", "td", "th", "tr"):
                    out.append(" ")
        return " ".join("".join(out).split())

    def find_all(self, pred: object) -> list[Node]:
        found: list[Node] = []
        for c in self.children:
            if isinstance(c, Node):
                if pred(c):  # type: ignore[operator]
                    found.append(c)
                found += c.find_all(pred)
        return found


class TreeBuilder(HTMLParser):
    """Tolerant tree builder: void tags never nest, unmatched end tags are ignored."""

    def __init__(self) -> None:
