    assert policy.add_months(date(2026, 5, 31), 9) == date(2027, 2, 28)
    assert policy.add_months(date(2027, 5, 31), 9) == date(2028, 2, 29)
    assert policy.add_months(date(2026, 1, 15), 9) == date(2026, 10, 15)


