    for c in label.expected_conflicts:
        for f in c.fields:
            if label.reference_profile.get(f) is not None:
                e.append(f"{cid}: conflicting field {f} must be None in the reference profile")
    for p in label.prohibited_conclusions:
        for b in p.basis:
