    leaks = [(a, b, s) for a, b, s in cross if a[:3] != b[:3]]
    out: dict[str, Any] = {"dev_cases": len(dev), "test_inputs": len(test_inputs),
                           "cross_split_near_duplicates": leaks, "errors": errors}
